<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QR Absensi - Hadiriin</title><style>body{background:#100c12;color:#fff;font-family:Inter,Arial,sans-serif;margin:0}nav{background:#171119;padding:18px 6%;display:flex;gap:20px;align-items:center;flex-wrap:wrap}a{color:#ff54ad;text-decoration:none}main{max-width:1000px;margin:30px auto;padding:0 18px}h1{color:#ff54ad}.panel{background:#1b151e;border:1px solid #713052;border-radius:16px;padding:24px;margin:18px 0}input,select,button{padding:12px;border-radius:9px;border:1px solid #713052;margin:6px;background:#251a28;color:white;font-size:15px}button{background:#a52d70;cursor:pointer}button:hover{background:#c83b8a}.success{color:#77e7a0}.error{color:#ff8f9c}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #473347;text-align:left}.muted{color:#b5a5b5}#qr{background:white;padding:16px;display:inline-block;border-radius:10px}video{max-width:100%}@media(max-width:600px){table{font-size:12px}td,th{padding:6px}}</style></head><body><nav><strong>Hadiriin.</strong><a href="{{route('dosen.dashboard')}}">Dashboard</a><a href="{{route('dosen.qr.index')}}">Kembali ke Sesi</a></nav><main><h1>{{$sesi->judul}}</h1><p class="muted">QR berubah otomatis setiap 15 detik. Mahasiswa harus login dan memindai menggunakan menu Scan QR.</p><div class="panel" style="text-align:center"><div id="qr"></div><p id="status">Memuat QR...</p><p id="countdown"></p><p>Berakhir: {{$sesi->berakhir_at->format('d M Y H:i:s')}}</p></div><form method="POST" action="{{route('dosen.qr.tutup',$sesi)}}">@csrf<button onclick="return confirm('Tutup sesi ini?')">Tutup Sesi</button></form></main><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>
const endpoint=@json(route('dosen.qr.token',$sesi));let previous='';async function update(){try{const r=await fetch(endpoint,{cache:'no-store',credentials:'same-origin'});if(!r.ok)throw new Error('Sesi telah berakhir atau tidak aktif');const d=await r.json();if(d.payload!==previous){previous=d.payload;const el=document.getElementById('qr');el.innerHTML='';if(typeof QRCode==='undefined')throw new Error('Library QR gagal dimuat. Periksa internet.');new QRCode(el,{text:d.payload,width:260,height:260,correctLevel:QRCode.CorrectLevel.M});}document.getElementById('status').textContent='QR aktif';document.getElementById('countdown').textContent='Berganti dalam '+d.seconds_left+' detik';}catch(e){document.getElementById('status').textContent=e.message;document.getElementById('qr').innerHTML='';}}update();setInterval(update,1000);
</script></body></html>